import{c as a,Q as s,j as l,m as n}from"./chunks/framework.DOi4mjdC.js";const e="/assets/%E4%BC%98%E5%8C%96%E5%89%8DProfiling%E6%95%B0%E6%8D%AE-86.CQ_BIAUn.png",p="/assets/%E6%9C%AA%E5%BC%80%E5%90%AFIBShare.DchwF0h6.png",o="/assets/matmul%E7%AE%97%E5%AD%90%E8%AE%A1%E7%AE%97%E6%B5%81%E7%A8%8B%E5%9B%BE-87.J75zgJ1H.png",i="/assets/NoABshare.BSyVewq6.png",r="/assets/%E4%BC%98%E5%8C%96%E5%90%8EProfiling%E6%95%B0%E6%8D%AE.zJudvm4i.png",q=JSON.parse('{"title":"Matmul高阶API使能IBShare模板共享A和B矩阵数据","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul高阶API使能IBShare模板共享A和B矩阵数据","slug":"matmul高阶api使能ibshare模板共享a和b矩阵数据"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能IBShare模板共享A和B矩阵数据.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能IBShare模板共享A和B矩阵数据.md"}'),c={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能IBShare模板共享A和B矩阵数据.md"};function u(g,t,d,h,_,b){return s(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="matmul高阶api使能ibshare模板共享a和b矩阵数据" tabindex="-1">Matmul高阶API使能IBShare模板共享A和B矩阵数据 <a class="header-anchor" href="#matmul高阶api使能ibshare模板共享a和b矩阵数据" aria-label="Permalink to &quot;Matmul高阶API使能IBShare模板共享A和B矩阵数据&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例呈现了在融合算子场景中，使用Matmul高阶API进行矩阵乘法计算时，A矩阵和B矩阵同时启用IBShare对性能的提升效果。</p><p>该案例的关键优化措施包括：</p><ul><li>分核逻辑：以Cube核视角分核，Matmul计算结果输出到GM，提供给Vector核进行后续计算。</li><li>开启IBShare：A矩阵和B矩阵同时开启IBShare。</li></ul><p>本案例的算子规格如下：</p><p><strong>表 1</strong> 算子规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;x&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;128,384&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;y&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;384,256&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>开启IBShare和未开启IBShare的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_ibshareAB" target="_blank" rel="noreferrer">A、B矩阵均使能IBShare样例</a>。</p><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取算子的Profiling的数据，重点分析MTE2，Cube，Scalar的流水情况。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><p><strong>图 1</strong> 优化前Profiling数据<br><img src="'+e+'" alt="" title="优化前Profiling数据-86"></p><p>通过分析以上Profiling数据可以看出，算子执行多次的平均耗时为27.11us，aic_scalar_time的平均耗时为26.27us，当前性能瓶颈点为Cube的Scalar流水。</p><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>A矩阵和B矩阵均未开启IBShare时，数据需要根据K轴、M轴或N轴进行切分计算。这里以K轴切分为例，未开启IBShare之前，算子以AIV Block为视角进行tiling切分，AIV0发起A0*B0的计算，AIV1发起A1*B1的计算。</p><p><strong>图 2</strong> 未开启IBShare<br><img src="'+p+'" alt="" title="未开启IBShare"></p><p>当A矩阵和B矩阵都启用IBShare时，可以一次性加载到L1 Buffer上，省去了切分，分开搬运的过程，同时Cube计算单元完全由AIV0单核驱动，发起一次计算，计算的结果由AIV0和AIV1共享，从而减少Cube响应的次数，减少Scalar计算。</p><p><strong>图 3</strong> 开启IBShare</p><p><img src="'+o+'" alt=""></p><p>开启IBShare和不开启IBShare的数据交互对比示意图如下：</p><p><img src="'+i+`" alt=""></p><p>通过设置A和B矩阵MatmulType的IBShare均为true，开启该优化，具体代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constexpr bool isABshare = true;</span></span>
<span class="line"><span>template &lt;typename aType, typename bType, typename cType&gt; class MatmulABshareKernel {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    __aicore__ inline MatmulABshareKernel(){};</span></span>
<span class="line"><span>    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR workspace,</span></span>
<span class="line"><span>                                const TCubeTiling &amp;tiling, AscendC::TPipe *pipe);</span></span>
<span class="line"><span>    __aicore__ inline void Process(AscendC::TPipe *pipe);</span></span>
<span class="line"><span>    __aicore__ inline void CalcOffset(int32_t blockIdx, const TCubeTiling &amp;tiling, int32_t &amp;offsetA, int32_t &amp;offsetB,</span></span>
<span class="line"><span>                                      int32_t &amp;offsetC);</span></span>
<span class="line"><span>    AscendC::Matmul&lt;AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, aType, false, LayoutMode::NONE, isABshare&gt;, </span></span>
<span class="line"><span>           AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, bType, false, LayoutMode::NONE, isABshare&gt;,</span></span>
<span class="line"><span>           AscendC::MatmulType&lt;AscendC::TPosition::VECIN, CubeFormat::ND, cType&gt;&gt;</span></span>
<span class="line"><span>        matmulObj;</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;aType&gt; aGlobal;</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;bType&gt; bGlobal;</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;cType&gt; cGlobal;</span></span>
<span class="line"><span>    TCubeTiling tiling;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>template &lt;typename aType, typename bType, typename cType&gt;</span></span>
<span class="line"><span>__aicore__ inline void MatmulABshareKernel&lt;aType, bType, cType&gt;::Init(GM_ADDR a, GM_ADDR b, GM_ADDR c, </span></span>
<span class="line"><span>                                                                GM_ADDR workspace,const TCubeTiling &amp;tiling, AscendC::TPipe *pipe)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    this-&gt;tiling = tiling;</span></span>
<span class="line"><span>    aGlobal.SetGlobalBuffer(reinterpret_cast&lt;__gm__ aType *&gt;(a), tiling.M * tiling.Ka);</span></span>
<span class="line"><span>    bGlobal.SetGlobalBuffer(reinterpret_cast&lt;__gm__ bType *&gt;(b), tiling.Kb * tiling.N);</span></span>
<span class="line"><span>    cGlobal.SetGlobalBuffer(reinterpret_cast&lt;__gm__ cType *&gt;(c), tiling.M * tiling.N);</span></span>
<span class="line"><span>    int32_t offsetA, offsetB, offsetC;</span></span>
<span class="line"><span>    CalcOffset(AscendC::GetBlockIdx(), tiling, offsetA, offsetB, offsetC); // calculate offset</span></span>
<span class="line"><span>    aGlobal = aGlobal[offsetA];</span></span>
<span class="line"><span>    bGlobal = bGlobal[offsetB];</span></span>
<span class="line"><span>    cGlobal = cGlobal[offsetC];</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>template &lt;typename aType, typename bType, typename cType&gt;</span></span>
<span class="line"><span>__aicore__ inline void</span></span>
<span class="line"><span>MatmulABshareKernel&lt;aType, bType, cType&gt;::CalcOffset(int32_t blockIdx, const TCubeTiling &amp;tiling,</span></span>
<span class="line"><span>                                                             int32_t &amp;offsetA, int32_t &amp;offsetB, int32_t &amp;offsetC)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    offsetA = 0;</span></span>
<span class="line"><span>    offsetB = 0;</span></span>
<span class="line"><span>    offsetC = 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><p>优化后执行多次的平均耗时：22.44us，较优化前有较大提升。</p><p><strong>图 4</strong> 优化后Profiling数据<br><img src="`+r+'" alt="" title="优化后Profiling数据"></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>融合算子场景下，Matmul A矩阵和B矩阵同时开启IBShare，以Cube核视角分核，可以有效减少Cube侧的Scalar开销，提升性能。</p>',29)])])}const A=a(c,[["render",u]]);export{q as __pageData,A as default};
